fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // If maxsplit is 0, per requirements, do no splitting
    // Return each string as a single-element vector.
    if maxsplit == 0 {
        return a.into_iter().map(|s| vec![s]).collect();
    }

    let maxsplit_usize = maxsplit as usize;

    a.into_iter()
        .map(|s| {
            if s.is_empty() {
                // Empty string produces one empty string in a vec
                vec![String::new()]
            } else {
                // Use rsplitn with (maxsplit+1) parts to produce at most maxsplit splits from right
                // rsplitn returns an iterator of &str in reverse order from right,
                // so after collection we reverse to get left-to-right ordering.
                let mut parts: Vec<String> =
                    s.rsplitn(maxsplit_usize + 1, &sep).map(|x| x.to_string()).collect();
                parts.reverse();
                parts
            }
        })
        .collect()
}